async function persistAdminData(data){const categories=(data.categories||[]).filter((category)=>category.slug||category.name).map((category,index)=>({slug:category.slug||category.name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''),name:category.name,cover_photo:category.photo||null,sort_order:index,active:true}));if(categories.length)await window.beadSupabase.from('categories').upsert(categories,{onConflict:'slug'});const productEntries=Object.entries(data.products||{});const products=productEntries.map(([externalId,product])=>({external_id:externalId,name:product.name||externalId,sku:product.sku||null,category_slug:product.category||'uncategorized',seo_title:product.seoTitle||product.name||externalId,search_text:[product.seoTitle,product.name,product.tags,product.description,product.materials].filter(Boolean).join(' '),description:product.description||null,item_details:product.details||null,shipping_details:product.shipping||null,price:Number(product.price)||0,quantity:Number(product.quantity)||0,visible:product.visible===true,waitlist_enabled:product.waitlist!==false}));if(!products.length)return;const {data:savedProducts}=await window.beadSupabase.from('products').upsert(products,{onConflict:'external_id'}).select('id,external_id');for(const saved of savedProducts||[]){const source=data.products[saved.external_id]||{};await window.beadSupabase.from('product_images').delete().eq('product_id',saved.id);const imageUrls=String(source.photos||'').split(/\s*[,\n]\s*/).map((url)=>url.trim()).filter(Boolean);if(imageUrls.length)await window.beadSupabase.from('product_images').insert(imageUrls.map((url,index)=>({product_id:saved.id,url,sort_order:index})));await window.beadSupabase.from('product_options').delete().eq('product_id',saved.id);let options=[];try{options=JSON.parse(source.options||'[]');}catch(error){options=[];}for(const [optionIndex,option] of options.entries()){const {data:savedOptions}=await window.beadSupabase.from('product_options').insert({product_id:saved.id,name:String(option.name||'Option'),required:option.required===true,sort_order:optionIndex}).select('id').single();if(!savedOptions?.id)continue;const values=(option.values||[]).map((value,valueIndex)=>({option_id:savedOptions.id,label:String(value.label||value),price_delta:Number(value.price||0),sort_order:valueIndex}));if(values.length)await window.beadSupabase.from('product_option_values').insert(values);}}}
const adminSafe=(value)=>String(value??'').replace(/[&<>"']/g,(character)=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[character]));
