  const start=selectedPeriod==='week'?new Date(end.getTime()-7*24*60*60*1000):selectedPeriod==='year'?new Date(end.getFullYear(),0,1):selectedPeriod==='all'?null:new Date(end.getFullYear(),end.getMonth(),1);
