const optimizeAdminImage=async(file)=>{if(!file||!file.type.startsWith('image/')||typeof createImageBitmap!=='function')return file;try{const bitmap=await createImageBitmap(file,{imageOrientation:'from-image'});const maxDimension=2400;const scale=Math.min(1,maxDimension/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const context=canvas.getContext('2d');if(!context){bitmap.close();return file;}context.drawImage(bitmap,0,0,canvas.width,canvas.height);const blob=await new Promise((resolve)=>canvas.toBlob(resolve,'image/webp',0.82));bitmap.close();if(!blob||blob.size>=file.size)return file;const baseName=file.name.replace(/\.[^.]+$/,'').replace(/[^a-z0-9._-]+/gi,'-').replace(/^-|-$/g,'')||'media';return new File([blob],`${baseName}.webp`,{type:'image/webp',lastModified:file.lastModified});}catch(error){return file;}};
const optimizeAdminVideo=async(file)=>{if(!file||!file.type.startsWith('video/')||typeof MediaRecorder==='undefined')return file;const sourceUrl=URL.createObjectURL(file);const video=document.createElement('video');video.muted=true;video.playsInline=true;video.src=sourceUrl;let stream=null;try{await new Promise((resolve,reject)=>{video.onloadedmetadata=resolve;video.onerror=reject;});stream=video.captureStream?.();const mimeType=['video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm'].find((type)=>MediaRecorder.isTypeSupported(type));if(!stream||!mimeType)return file;const chunks=[];const recorder=new MediaRecorder(stream,{mimeType,videoBitsPerSecond:2000000,audioBitsPerSecond:128000});const finished=new Promise((resolve,reject)=>{recorder.ondataavailable=(event)=>{if(event.data.size)chunks.push(event.data);};recorder.onerror=()=>reject(recorder.error||new Error('Video compression failed.'));recorder.onstop=()=>resolve(new Blob(chunks,{type:mimeType}));});await video.play();recorder.start();await new Promise((resolve,reject)=>{video.onended=resolve;video.onerror=reject;});recorder.stop();const blob=await finished;if(!blob||blob.size>=file.size)return file;const baseName=file.name.replace(/\.[^.]+$/,'').replace(/[^a-z0-9._-]+/gi,'-').replace(/^-|-$/g,'')||'video';return new File([blob],`${baseName}.webm`,{type:mimeType,lastModified:file.lastModified});}catch(error){return file;}finally{stream?.getTracks().forEach((track)=>track.stop());URL.revokeObjectURL(sourceUrl);}};
const uploadAdminMedia=async(file,folder)=>{if(!file)return null;if(file.type.startsWith('video/')&&file.size>100*1024*1024)throw new Error('Videos must be 100 MB or smaller.');const optimized=file.type.startsWith('video/')?await optimizeAdminVideo(file):await optimizeAdminImage(file);if(optimized.type.startsWith('video/')&&optimized.size>100*1024*1024)throw new Error('Videos must be 100 MB or smaller.');const safeName=optimized.name.toLowerCase().replace(/[^a-z0-9._-]+/g,'-');const path=`${folder}/${Date.now()}-${safeName}`;const result=await cloudAdmin().storage.from('product-media').upload(path,optimized,{upsert:false,contentType:optimized.type||undefined,cacheControl:'31536000'});if(result.error)adminFailure(result.error);return cloudAdmin().storage.from('product-media').getPublicUrl(path).data.publicUrl;};
const adminProductRows=async()=>{const rows=[];const pageSize=1000;for(let from=0;;from+=pageSize){const result=await cloudAdmin().from('products').select('id,external_id,sku,category_slug,name,search_text,price,promo_price,promo_starts_at,promo_ends_at,promo_discount_percent,promo_skus,quantity,visible,waitlist_enabled,estimated_cost,low_stock_threshold,badges,product_images(id,url,sort_order,media_type),product_options(product_option_values(sku,inventory_sku))').order('name').range(from,from+pageSize-1);if(result.error)adminFailure(result.error);rows.push(...(result.data||[]));if((result.data||[]).length<pageSize)break;}rows.forEach((product)=>{const skus=[...new Set((product.product_options||[]).flatMap((option)=>option.product_option_values||[]).map((value)=>String(value.sku||value.inventory_sku||'').trim()).filter(Boolean))];product.sku=skus.join(', ')||product.sku||'';});return rows;};
