const cloudCategoryForm=async(id=null)=>{let category={name:'',slug:'',cover_photo:'',active:true};if(id){const categories=await cloudCategoryRows();category=categories.find((entry)=>entry.id===id)||category;}panel.innerHTML=`<div class="admin-heading"><div><p class="kicker">CATEGORY EDITOR</p><h2>${id?'Edit category':'Add category'}</h2></div></div><form class="admin-form" id="cloud-category-form"><label>Name<input name="name" required value="${adminSafe(category.name)}"></label><label>Slug (optional; custom slugs are supported)<input name="slug" value="${adminSafe(category.slug)}" placeholder="Generated from name"><small>Changing a slug updates products assigned to this category.</small></label><fieldset class="admin-media-editor"><legend>Category image</legend><label>Image source<select name="cover_source"><option value="url" ${category.cover_photo?'selected':''}>Image URL</option><option value="upload" ${category.cover_photo?'':'selected'}>Upload image</option></select></label><label>Image URL<input name="cover_photo" type="url" value="${adminSafe(category.cover_photo||'')}" placeholder="https://..."></label><label>Upload image<input name="cover" type="file" accept="image/*"></label></fieldset><label class="admin-toggle"><input name="active" type="checkbox" ${category.active?'checked':''}> Visible in storefront navigation</label><div class="admin-actions"><button class="cta">Save category</button><button type="button" data-cancel>Cancel</button></div></form>`;const form=panel.querySelector('form');const source=form.querySelector('[name="cover_source"]');const syncImageSource=()=>{const useUrl=source.value==='url';form.querySelector('[name="cover_photo"]').disabled=!useUrl;form.querySelector('[name="cover"]').disabled=useUrl;};source.addEventListener('change',syncImageSource);syncImageSource();panel.querySelector('[data-cancel]').addEventListener('click',renderCloudCategories);form.addEventListener('submit',async(event)=>{event.preventDefault();const fields=Object.fromEntries(new FormData(form));const slug=adminSlug(fields.slug||fields.name);if(!slug)return renderCloudError(new Error('Category name is required.'));const file=form.querySelector('[name="cover"]').files[0];try{let cover=source.value==='url'?String(fields.cover_photo||'').trim()||null:category.cover_photo||null;if(source.value==='upload'&&file)cover=await uploadAdminMedia(file,`categories/${slug}`);const payload={slug,name:fields.name,cover_photo:cover,active:form.active.checked,sort_order:category.sort_order??999};const result=id?await cloudAdmin().from('categories').update(payload).eq('id',id).select('id,slug').single():await cloudAdmin().from('categories').insert(payload).select('id,slug').single();if(result.error)adminFailure(result.error);if(id&&category.slug!==slug){const move=await cloudAdmin().from('products').update({category_slug:slug}).eq('category_slug',category.slug);if(move.error)adminFailure(move.error);}renderCloudCategories();}catch(error){renderCloudError(error);}});};
renderItems=async()=>{if(!cloudAdmin()){renderCloudError(new Error('Supabase is not connected.'));return;}try{const products=await adminProductRows();let activeTab='live';let currentPage=1;const pageSize=25;const categories=[...new Set(products.map((product)=>product.category_slug||'uncategorized'))].sort();const productTitle=(product)=>product.name&&product.name!=='1'?product.name:product.external_id||product.sku||'Untitled product';const leadImage=(product)=>product.product_images?.find((media)=>media.media_type!=='video')?.url||'product-mix.jpg';const row=(product)=>`<tr><td><img class="admin-product-lead" loading="lazy" src="${adminSafe(leadImage(product))}" alt="${adminSafe(productTitle(product))}"></td><td><strong>${adminSafe(productTitle(product))}</strong></td><td>${adminSafe(product.sku||'—')}</td><td>$${Number(product.price).toFixed(2)}</td><td>${Number(product.quantity)||0}</td><td><button data-toggle-visible="${product.id}">${product.visible?'ON':'OFF'}</button></td><td><a href="admin?edit=${encodeURIComponent(product.id)}">Edit</a></td></tr>`;const table=(title,items,total)=>`<section class="admin-card"><h3>${title} <span>(${total})</span></h3><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Lead image</th><th>Product title</th><th>SKU</th><th>Price</th><th>Stock</th><th>Storefront</th><th></th></tr></thead><tbody>${items.map(row).join('')||'<tr><td colspan="7">No matching products.</td></tr>'}</tbody></table></div></section>`;panel.innerHTML=`<div class="admin-heading"><div><p class="kicker">PRODUCT CATALOG</p><h2>Products/SKUs</h2><p>Every product is listed here, whether it is live or deactivated.</p></div><a class="cta" href="admin?new=item">Add item</a></div><div class="admin-form-grid"><label>Search products<input id="cloud-item-search" type="search" placeholder="Name, SKU, category, or description"></label><label>Filter<select id="cloud-item-filter"><option value="all">All products</option><option value="promo">Active promos</option><option value="clearance">Clearance</option><option value="in-stock">In stock</option><option value="low-stock">Low stock</option><option value="out-of-stock">Out of stock</option></select></label><label>Category<select id="cloud-item-category"><option value="all">All categories</option>${categories.map((category)=>`<option value="${adminSafe(category)}">${adminSafe(category)}</option>`).join('')}</select></label><label>Sort by<select id="cloud-item-sort"><option value="name">Name</option><option value="category">Category</option><option value="sku">SKU</option><option value="price">Price</option><option value="quantity">Stock</option><option value="updated">Recently added</option></select></label></div><div class="admin-tabs"><button type="button" data-items-tab="live" aria-selected="true">Live products</button><button type="button" data-items-tab="deactivated" aria-selected="false">Deactivated products</button></div><div id="cloud-items-lists"></div><div id="cloud-items-pagination" class="admin-pagination"></div>`;const hasActivePromo=(product)=>product.promo_price!==null&&product.promo_price!==''&&(!product.promo_starts_at||Date.parse(product.promo_starts_at)<=Date.now())&&(!product.promo_ends_at||Date.parse(product.promo_ends_at)>=Date.now());const isClearance=(product)=>String(product.category_slug||'').toLowerCase().includes('clearance')||(product.badges||[]).some((badge)=>String(badge).toLowerCase()==='clearance');const inventoryState=(product)=>Number(product.quantity||0)<=0?'out-of-stock':Number(product.low_stock_threshold||0)>0&&Number(product.quantity||0)<=Number(product.low_stock_threshold||0)?'low-stock':'in-stock';const draw=()=>{const needle=panel.querySelector('#cloud-item-search').value.trim().toLowerCase();const filter=panel.querySelector('#cloud-item-filter').value;const category=panel.querySelector('#cloud-item-category').value;const sort=panel.querySelector('#cloud-item-sort').value;const matching=products.filter((product)=>category==='all'||(product.category_slug||'uncategorized')===category).filter((product)=>[product.name,product.external_id,product.sku,product.category_slug,product.description,product.item_details,product.shipping_details].filter(Boolean).join(' ').toLowerCase().includes(needle)).filter((product)=>filter==='promo'?hasActivePromo(product):filter==='clearance'?isClearance(product):['in-stock','low-stock','out-of-stock'].includes(filter)?inventoryState(product)===filter:true).sort((a,b)=>{if(sort==='price'||sort==='quantity')return Number(a[sort]||0)-Number(b[sort]||0);if(sort==='updated')return String(b.added_at||'').localeCompare(String(a.added_at||''));return String(a[sort]||a.name||a.external_id||'').localeCompare(String(b[sort]||b.name||b.external_id||''));});const tabProducts=matching.filter((product)=>activeTab==='live'?product.visible:!product.visible);const pageCount=Math.max(1,Math.ceil(tabProducts.length/pageSize));currentPage=Math.min(currentPage,pageCount);const pageItems=tabProducts.slice((currentPage-1)*pageSize,currentPage*pageSize);panel.querySelector('#cloud-items-lists').innerHTML=table(activeTab==='live'?'Live products':'Deactivated products',pageItems,tabProducts.length);panel.querySelector('#cloud-items-pagination').innerHTML=`<button type="button" data-items-prev ${currentPage===1?'disabled':''}>Previous</button><span>Page ${currentPage} of ${pageCount} · ${tabProducts.length} products</span><button type="button" data-items-next ${currentPage===pageCount?'disabled':''}>Next</button>`;panel.querySelectorAll('[data-items-tab]').forEach((button)=>{button.setAttribute('aria-selected',button.dataset.itemsTab===activeTab?'true':'false');button.onclick=()=>{activeTab=button.dataset.itemsTab;currentPage=1;draw();};});panel.querySelector('[data-items-prev]').onclick=()=>{currentPage=Math.max(1,currentPage-1);draw();};panel.querySelector('[data-items-next]').onclick=()=>{currentPage=Math.min(pageCount,currentPage+1);draw();};bindRows();};const bindRows=()=>{panel.querySelectorAll('[data-edit-cloud-item]').forEach((button)=>button.onclick=()=>{void cloudItemForm(button.dataset.editCloudItem).catch(renderCloudError)});panel.querySelectorAll('[data-toggle-visible]').forEach((button)=>button.addEventListener('click',async()=>{const product=products.find((entry)=>entry.id===button.dataset.toggleVisible);const result=await cloudAdmin().from('products').update({visible:!product.visible}).eq('id',product.id);if(result.error)return renderCloudError(result.error);renderItems();}));};panel.querySelector('#cloud-item-search').addEventListener('input',()=>{currentPage=1;draw();});panel.querySelector('#cloud-item-filter').addEventListener('change',()=>{currentPage=1;draw();});panel.querySelector('#cloud-item-category').addEventListener('change',()=>{currentPage=1;draw();});panel.querySelector('#cloud-item-sort').addEventListener('change',()=>{currentPage=1;draw();});draw();}catch(error){renderCloudError(error);}};


const cloudItemForm=async(id=null)=>{const products=id?await adminProductDetail(id):[];const product=products.find((entry)=>entry.id===id)||{name:'',sku:'',category_slug:'',shortDescription:'',description:'',item_details:'',shipping_details:'',promo_discount_percent:0,estimated_cost:'',promo_skus:[],visible:false,waitlist_enabled:false,badges:[],product_images:[]};const categories=await cloudCategoryRows();const badges=['Acrylic','Silicone','Rhinestones','12mm','12mm Lentil','14mm','14mm Abacus','15mm','16mm','18mm','20mm','Fits on Beadable Pen','On Sale','Clearance','Low Stock','Out of Stock'];const existingMedia=product.product_images||[];panel.innerHTML=`<div class="admin-heading"><div><p class="kicker">ITEM EDITOR</p><h2>${id?'Edit item':'Add item'}</h2><p>Each product page is a group of customer-selectable SKUs.</p></div></div><form class="admin-form admin-item-form" id="cloud-item-form" data-product-id="${id||""}"><label>Product name<input name="name" required value="${adminSafe(product.name)}"></label><div class="admin-item-meta-row"><label>Category<select name="category_slug" required><option value="">Choose a category</option>${categories.map((category)=>`<option value="${adminSafe(category.slug)}" ${product.category_slug===category.slug?'selected':''}>${adminSafe(category.name)}</option>`).join('')}</select></label><label class="admin-toggle"><input name="visible" type="checkbox" ${product.visible?'checked':''}><span>On / listed in storefront</span></label><label class="admin-toggle"><input name="waitlist_enabled" type="checkbox" ${product.waitlist_enabled?'checked':''}><span>Waitlist available</span></label></div><details class="admin-variant-editor" open><summary>SKUs</summary><p>Start with one SKU. Add, remove, or reorder unlimited SKUs; the first row is shown first on the product page.</p><div data-variant-list></div><button type="button" data-add-variant>Add another SKU</button></details><details class="admin-promo-editor" open><summary>Promos</summary><div class="admin-form-grid"><label>Discount %<input name="promo_discount_percent" type="number" min="0" max="100" step="1" value="${Number(product.promo_discount_percent)||0}"></label><label>Starts<input name="promo_starts_at" type="datetime-local" value="${product.promo_starts_at?product.promo_starts_at.slice(0,16):''}"></label><label>Ends<input name="promo_ends_at" type="datetime-local" value="${product.promo_ends_at?product.promo_ends_at.slice(0,16):''}"></label></div><p>Select which SKUs this promotion affects.</p><div data-promo-sku-list></div><input type="hidden" name="promo_skus" value=""></details><fieldset class="admin-badge-picker"><legend>Badges</legend>${badges.map((badge)=>`<label><input type="checkbox" name="badges" value="${adminSafe(badge)}" ${(product.badges||[]).includes(badge)?'checked':''}> <span class="product-badge badge-${adminSlug(badge)}">${adminSafe(badge)}</span></label>`).join('')}</fieldset><fieldset class="admin-media-editor"><legend>Photos and videos</legend><p>Existing media can be edited or removed. Uploaded images are compressed before storage.</p>${existingMedia.map((media)=>`<div class="admin-media-row" data-existing-media data-media-id="${adminSafe(media.id)}"><input data-display-name value="${adminSafe(adminMediaName(media.url,media.alt_text))}" aria-label="Photo display name" placeholder="Display name"><input data-existing-url value="${adminSafe(media.url||'')}" aria-label="Media URL"><select data-existing-type aria-label="Media type"><option value="image" ${media.media_type!=='video'?'selected':''}>Image</option><option value="video" ${media.media_type==='video'?'selected':''}>Video</option></select><button type="button" data-remove-media>Remove</button></div>`).join('')||'<p>No media saved yet.</p>'}<div data-manual-url-list><div class="admin-media-row" data-manual-media><input data-display-name placeholder="Display name (optional)" aria-label="New media display name"><input data-manual-url placeholder="https://..." aria-label="New media URL"><select data-manual-type aria-label="New media type"><option value="image">Image</option><option value="video">Video</option></select><button type="button" data-remove-manual>Remove</button></div></div><button type="button" data-add-manual>Add media link</button><label>Upload new photos or videos<input name="media" type="file" accept="image/*,video/*" multiple><small>Videos are limited to 100 MB.</small></label></fieldset><label>Short description<textarea name="short_description" rows="3" placeholder="A brief customer-facing summary shown beside the product name.">${adminSafe(product.short_description||product.shortDescription||'')}</textarea></label><label>Full product description<textarea name="description" rows="5">${adminSafe(product.description||'')}</textarea></label><label>Item details for search only<textarea name="item_details" rows="4" placeholder="Not shown to customers. Add keywords, materials, sizing, and internal search terms.">${adminSafe(product.item_details||'')}</textarea></label><section class="admin-shipping-editor"><h3>Shipping details</h3><p>Uses the default shipping and returns policy from Store settings unless you enable the override.</p><label class="admin-toggle admin-shipping-override"><input name="shipping_override" type="checkbox" ${product.shipping_details?'checked':''}><span>Override default shipping details for this product</span></label><textarea name="shipping_details" rows="4" ${product.shipping_details?'':'disabled'}>${adminSafe(product.shipping_details||'')}</textarea></section><details class="admin-etsy-editor" open><summary>Etsy mapping</summary><p>Backend-only conversion rows. Each Etsy SKU maps to an inventory SKU and the quantity deducted per Etsy unit.</p><div data-etsy-list></div><button type="button" data-add-etsy>Add Etsy mapping</button></details><input type="hidden" name="sku_data" value=""><input type="hidden" name="etsy_mappings" value=""><div class="admin-actions"><button class="cta">Save item</button><button type="button" data-cancel>Cancel</button></div></form>`;const form=panel.querySelector('form');const makeManualMediaRow=()=>{const row=document.createElement('div');row.className='admin-media-row';row.dataset.manualMedia='';row.innerHTML='<input data-display-name placeholder="Display name (optional)" aria-label="New media display name"><input data-manual-url placeholder="https://..." aria-label="New media URL"><select data-manual-type aria-label="New media type"><option value="image">Image</option><option value="video">Video</option></select><button type="button" data-remove-manual>Remove</button>';row.querySelector('[data-remove-manual]').onclick=()=>row.remove();return row;};form.querySelectorAll('[data-existing-media]').forEach((row)=>{const removeButton=row.querySelector('[data-remove-media]');removeButton.checked=false;removeButton.onclick=()=>{removeButton.checked=true;row.hidden=true;};});renderAdminVariantEditor(form,[],existingMedia,product);renderAdminPromoEditor(form,product.promo_skus||[]);renderAdminEtsyEditor(form,[]);initializeAdminCollapsibleSections(form);normalizeAdminSkuRows(form);ensureAdminQtySoldBadgeChoice(form);setupAdminExistingSkuLookup(form);void renderAdminInventoryHistory(form);if(!id)void initializeAdminBundleEditor(form);const saveButton=form.querySelector('button.cta');if(id)saveButton.disabled=true;if(id)loadAdminProductChildren(id).then((children)=>{if(!form.isConnected)return;renderAdminVariantEditor(form,children.options,existingMedia,product);renderAdminPromoEditor(form,product.promo_skus||[]);renderAdminEtsyEditor(form,[]);normalizeAdminSkuRows(form);ensureAdminQtySoldBadgeChoice(form);setupAdminExistingSkuLookup(form);void initializeAdminBundleEditor(form);saveButton.disabled=false;}).catch((error)=>{if(form.isConnected)renderCloudError(error);});const shippingOverride=form.querySelector('[name="shipping_override"]');const shippingDetails=form.querySelector('[name="shipping_details"]');shippingOverride.addEventListener('change',()=>{shippingDetails.disabled=!shippingOverride.checked;if(!shippingOverride.checked)shippingDetails.value='';});panel.querySelector('[data-cancel]').addEventListener('click',renderItems);panel.querySelector('[data-add-manual]').addEventListener('click',()=>form.querySelector('[data-manual-url-list]').append(makeManualMediaRow()));form.querySelectorAll('[data-manual-media] [data-remove-manual]').forEach((button)=>button.addEventListener('click',()=>button.closest('[data-manual-media]').remove()));form.addEventListener('submit',async(event)=>{event.preventDefault();try{await saveCloudProductWithBundles(id,Object.fromEntries(new FormData(event.currentTarget)),event.currentTarget);renderItems();}catch(error){renderCloudError(error);}});};

const loadAdminProductChildren=async(id)=>{if(!id)return{options:[],mappings:[]};const [optionResult,mappingResult]=await Promise.all([cloudAdmin().from('product_options').select('id,name,required,sort_order,product_option_values(id,label,inventory_sku_id,inventory_units,image_url,sort_order,inventory_skus(id,sku,name,variant_name,quantity_on_hand,reorder_point,item_type,hierarchy,category,taxable,price,cost,income_account,expense_account,inventory_asset_account,sales_description,purchase_description,preferred_vendor,unit_type,weight_value,weight_unit,reserve_quantity))').eq('product_id',id).order('sort_order'),cloudAdmin().from('product_etsy_mappings').select('id,etsy_sku,inventory_sku_id,inventory_units,active,sort_order,inventory_skus(id,sku,name)').eq('product_id',id).order('sort_order')]);if(optionResult.error)adminFailure(optionResult.error);if(mappingResult.error)adminFailure(mappingResult.error);return{options:optionResult.data||[],mappings:mappingResult.data||[]};};
const loadAdminProductChildrenWithBundles=async(id)=>{
  const children=await loadAdminProductChildren(id);
  const bundleIds=[...new Set((children.options||[]).flatMap((option)=>option.product_option_values||[]).map((value)=>value.inventory_sku_id).filter(Boolean))];
  if(!bundleIds.length)return{...children,components:[]};
  const result=await cloudAdmin().from('inventory_bundle_components').select('bundle_sku_id,component_sku_id,quantity,sort_order').in('bundle_sku_id',bundleIds).order('sort_order');
  if(result.error)adminFailure(result.error);
  const ids=[...new Set((result.data||[]).flatMap((row)=>[row.bundle_sku_id,row.component_sku_id]))];
  const lookup=ids.length?await cloudAdmin().from('inventory_skus').select('id,sku').in('id',ids):{data:[],error:null};
  if(lookup.error)adminFailure(lookup.error);
  const skuById=new Map((lookup.data||[]).map((row)=>[row.id,row.sku]));
  return{...children,components:(result.data||[]).map((row)=>({bundle_sku:skuById.get(row.bundle_sku_id)||'',component_sku:skuById.get(row.component_sku_id)||'',quantity:row.quantity,sort_order:row.sort_order}))};
};
