const renderAdminInventoryHistory=async(form)=>{const productId=form?.dataset.productId;if(!productId||form.dataset.inventoryHistoryLoaded)return;form.dataset.inventoryHistoryLoaded='loading';const [changeResult,adjustmentResult]=await Promise.all([cloudAdmin().from('product_change_history').select('id,inventory_sku,field_name,previous_value,new_value,change_type,note,created_at').eq('product_id',productId).order('created_at',{ascending:false}).range(0,199),cloudAdmin().from('inventory_adjustments').select('id,inventory_sku,quantity_delta,quantity_after,note,adjustment_type,cost_impact,created_at').eq('product_id',productId).order('created_at',{ascending:false}).range(0,199)]);if(!form.isConnected)return;if(changeResult.error||adjustmentResult.error){form.dataset.inventoryHistoryLoaded='error';return;}const entries=[...(changeResult.data||[]).map((entry)=>({...entry,historyType:'change'})),...(adjustmentResult.data||[]).map((entry)=>({inventory_sku:entry.inventory_sku,field_name:'Inventory quantity',previous_value:String(Number(entry.quantity_after)-Number(entry.quantity_delta)),new_value:String(entry.quantity_after),change_type:'updated',note:entry.note,adjustment_type:entry.adjustment_type,cost_impact:entry.cost_impact,created_at:entry.created_at,historyType:'adjustment'}))].sort((first,second)=>Date.parse(second.created_at)-Date.parse(first.created_at));const formatEntry=(entry)=>'<li><strong>'+adminSafe(entry.field_name)+'</strong><span>'+adminSafe(entry.inventory_sku||'Product')+' · '+new Date(entry.created_at).toLocaleString()+' · '+adminSafe(entry.change_type)+'</span><p>Previous: '+adminSafe(entry.previous_value??'—')+' → New: '+adminSafe(entry.new_value??'—')+(entry.note?' · '+adminSafe(entry.note):'')+(entry.historyType==='adjustment'?' · Source: '+adminSafe(String(entry.adjustment_type||'manual').replace(/_/g,' '))+(Number(entry.cost_impact)?' · Cost impact: $'+Number(entry.cost_impact).toFixed(2):''):'')+'</p></li>';const section=document.createElement('details');section.className='admin-card admin-inventory-history';section.innerHTML='<summary>Product change history</summary><p>Important product and inventory changes recorded for review.</p><ul>'+((entries.map(formatEntry).join(''))||'<li>No product changes recorded.</li>')+'</ul>';const actions=form.querySelector('.admin-actions');if(actions)actions.before(section);else form.append(section);form.dataset.inventoryHistoryLoaded='true';};
const initializeAdminSkuLayout=(form)=>{form.querySelectorAll('[data-variant-row]').forEach((row)=>{if(row.dataset.skuLayoutInitialized)return;const markField=(selector,className)=>{const label=row.querySelector(selector)?.closest('label');label?.classList.add(className);return label;};const nameLabel=markField('[data-variant-label]','admin-sku-name-field');markField('[data-variant-sku]','admin-sku-sku-field');const priceLabel=markField('[data-variant-price]','admin-sku-price-field');const priceInput=row.querySelector('[data-variant-price]');const unitInput=row.querySelector('[data-variant-unit-type]');const priceUnitWrap=unitInput?.closest('.admin-price-unit');if(priceLabel&&priceInput&&unitInput&&priceUnitWrap){priceUnitWrap.replaceWith(priceInput);const unitLabel=document.createElement('label');unitLabel.className='admin-sku-unit-field';unitLabel.append('Unit',unitInput);priceLabel.after(unitLabel);}const weightLabel=markField('[data-variant-weight]','admin-sku-weight-field');const weightInput=row.querySelector('[data-variant-weight]');const weightUnitLabel=row.querySelector('[data-variant-weight-unit]')?.closest('label');const weightUnitInput=row.querySelector('[data-variant-weight-unit]');if(weightLabel&&weightInput&&weightUnitLabel&&weightUnitInput){const weightInputs=document.createElement('div');weightInputs.className='admin-sku-weight-inputs';weightInput.replaceWith(weightInputs);weightInputs.append(weightInput,weightUnitInput);weightUnitLabel.remove();}const cost=row.querySelector('.admin-sku-cost');const costInput=cost?.querySelector('[data-variant-cost]');if(cost&&costInput){const costLabel=document.createElement('label');costLabel.className='admin-sku-cost-field';costLabel.append('Cost',costInput);cost.replaceWith(costLabel);weightLabel?.after(costLabel);}markField('[data-variant-quantity]','admin-sku-inventory-field');const thresholdLabel=markField('[data-variant-threshold]','admin-sku-threshold-field');const reserveInput=row.querySelector('[data-variant-reserve]');const reserveLabel=reserveInput?.closest('label');if(reserveInput&&reserveLabel&&thresholdLabel){const reserveField=document.createElement('label');reserveField.className='admin-sku-reserve-field';reserveField.append('Reserve buffer',reserveInput);reserveLabel.remove();thresholdLabel.after(reserveField);}markField('[data-variant-inventory-sku]','admin-sku-affected-field');markField('[data-variant-inventory-units]','admin-sku-deducted-field');markField('[data-variant-photo]','admin-sku-photo-field');row.dataset.skuLayoutInitialized='true';});};

