const initializeAdminCollapsibleSections=(form)=>{if(!form||form.dataset.collapsibleSectionsInitialized)return;form.dataset.collapsibleSectionsInitialized='true';form.querySelectorAll('.admin-variant-editor,.admin-promo-editor,.admin-etsy-editor').forEach((section)=>section.removeAttribute('open'));wrapAdminSection(form.querySelector('.admin-badge-picker'),'Badges','admin-collapsible-section admin-badges-section');wrapAdminSection(form.querySelector('.admin-media-editor'),'Photos and videos','admin-collapsible-section admin-photos-section');const description=wrapAdminSection(form.querySelector('textarea[name="description"]')?.closest('label'),'Description','admin-collapsible-section admin-content-editor-section');const itemDetails=wrapAdminSection(form.querySelector('textarea[name="item_details"]')?.closest('label'),'Item details','admin-collapsible-section admin-content-editor-section');const shipping=form.querySelector('.admin-shipping-editor');if(shipping&&shipping.tagName==='SECTION'){const shippingDetails=document.createElement('details');shippingDetails.className='admin-collapsible-section admin-content-editor-section admin-shipping-editor';const summary=document.createElement('summary');summary.textContent='Shipping details';shippingDetails.append(summary);[...shipping.childNodes].forEach((child)=>{if(child.nodeType===1&&child.matches('h3'))return;shippingDetails.append(child);});shipping.replaceWith(shippingDetails);}const contentSections=[description,itemDetails,form.querySelector('.admin-shipping-editor')].filter((section)=>section?.matches('details'));if(contentSections.length&&!form.querySelector('.admin-content-editor-group')){const group=document.createElement('details');group.className='admin-content-editor-group';const summary=document.createElement('summary');summary.textContent='Content and shipping';group.append(summary);contentSections[0].before(group);contentSections.forEach((section)=>group.append(section));}};
