const loadAdminSkuReferenceData=async()=>{
  const [inventory,products,options,mappings,mappingComponents,bundles]=await Promise.all([
    fetchAdminRowsAll(()=>cloudAdmin().from('inventory_skus').select('id,sku,name,variant_name,quantity_on_hand,item_type,preferred_vendor').order('sku')),
    fetchAdminRowsAll(()=>cloudAdmin().from('products').select('sku')),
    fetchAdminRowsAll(()=>cloudAdmin().from('product_option_values').select('sku,inventory_sku,inventory_sku_id')),
    fetchAdminRowsAll(()=>cloudAdmin().from('product_etsy_mappings').select('inventory_sku,inventory_sku_id')),
    fetchAdminRowsAll(()=>cloudAdmin().from('product_etsy_mapping_components').select('inventory_sku,inventory_sku_id')),
    fetchAdminRowsAll(()=>cloudAdmin().from('inventory_bundle_components').select('bundle_sku_id,component_sku_id'))
  ]);
  const skuById=new Map((inventory||[]).map((row)=>[row.id,row.sku]));
  return{inventory:inventory||[],products:products||[],options:options||[],mappings:mappings||[],mappingComponents:mappingComponents||[],bundles:(bundles||[]).map((row)=>({...row,bundle_sku:skuById.get(row.bundle_sku_id)||'',component_sku:skuById.get(row.component_sku_id)||''}))};
};
const renderAdminOrphanReportTab=async()=>{
  const view=panel.querySelector('#inventory-view');
  if(!view)return;
  view.innerHTML='<div class="admin-heading"><div><h3>Orphaned inventory SKUs</h3><p>Read-only report of canonical SKUs with no product, Etsy mapping, or bundle recipe reference. Use Products/SKUs for the guarded permanent-delete action.</p></div><button type="button" data-refresh-orphan-report>Refresh report</button><button type="button" data-download-orphan-report>Download CSV</button></div><p data-orphan-report-status>Loading canonical SKU references…</p><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>SKU</th><th>Name</th><th>Quantity</th><th>Item type</th><th>Preferred vendor</th></tr></thead><tbody></tbody></table></div>';
  const status=view.querySelector('[data-orphan-report-status]');
  try{
    const references=await loadAdminSkuReferenceData();
    const referenced=new Set();
    const addReference=(value)=>{const key=String(value||'').trim().toLowerCase();if(key)referenced.add(key);};
    references.products.forEach((row)=>addReference(row.sku));
    references.options.forEach((row)=>{addReference(row.sku);addReference(row.inventory_sku);});
    references.mappings.forEach((row)=>addReference(row.inventory_sku));
    references.mappingComponents.forEach((row)=>addReference(row.inventory_sku));
    references.bundles.forEach((row)=>{addReference(row.bundle_sku);addReference(row.component_sku);});
    const orphaned=references.inventory.filter((row)=>!referenced.has(String(row.sku||'').trim().toLowerCase()));
    view.querySelector('tbody').innerHTML=orphaned.map((row)=>'<tr><td>'+adminSafe(row.sku)+'</td><td>'+adminSafe(row.name||row.variant_name||'—')+'</td><td>'+Number(row.quantity_on_hand||0)+'</td><td>'+adminSafe(row.item_type||'—')+'</td><td>'+adminSafe(row.preferred_vendor||'—')+'</td></tr>').join('')||'<tr><td colspan="5">No unreferenced canonical SKUs found.</td></tr>';
    status.textContent=orphaned.length+' unreferenced canonical SKU'+(orphaned.length===1?'':'s')+' found.';
    view.querySelector('[data-download-orphan-report]').onclick=()=>{const link=document.createElement('a');const csv=[['SKU','Name','Quantity','Item type','Preferred vendor'],...orphaned.map((row)=>[row.sku,row.name||row.variant_name||'',row.quantity_on_hand,row.item_type||'',row.preferred_vendor||''])].map((row)=>row.map((value)=>'"'+String(value??'').replace(/"/g,'""')+'"').join(',')).join('\n');link.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));link.download='orphaned-inventory-skus.csv';link.click();};
    view.querySelector('[data-refresh-orphan-report]').onclick=()=>void renderAdminOrphanReportTab();
  }catch(error){status.textContent='Unable to load orphaned SKUs: '+error.message;}
};
const renderAdminUncategorizedReportTab=async()=>{const view=panel.querySelector('#inventory-view');if(!view)return;view.innerHTML='<div class="admin-heading"><div><h3>Products with no category</h3><p>Products that do not have a category assigned. Assign one from the Products/SKUs editor.</p></div><button type="button" data-refresh-uncategorized-report>Refresh report</button><button type="button" data-download-uncategorized-report>Download CSV</button></div><p data-uncategorized-report-status>Loading products…</p><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Product</th><th>SKU(s)</th><th>Storefront</th><th>Product ID</th></tr></thead><tbody></tbody></table></div>';const status=view.querySelector('[data-uncategorized-report-status]');try{const [products,options]=await Promise.all([fetchAdminRowsAll(()=>cloudAdmin().from('products').select('id,external_id,name,sku,category_slug,visible').order('name')),fetchAdminRowsAll(()=>cloudAdmin().from('product_option_values').select('option_id,sku,inventory_sku,product_options!inner(product_id)'))]);const skuByProduct=new Map();(options||[]).forEach((row)=>{const productId=row.product_options?.product_id;if(!productId)return;const values=skuByProduct.get(productId)||[];const sku=String(row.inventory_sku||row.sku||'').trim();if(sku&&!values.includes(sku))values.push(sku);skuByProduct.set(productId,values);});const uncategorized=(products||[]).filter((product)=>!String(product.category_slug||'').trim()).map((product)=>({...product,displaySkus:(skuByProduct.get(product.id)||[]).join(', ')||product.sku||'—'}));view.querySelector('tbody').innerHTML=uncategorized.map((product)=>'<tr><td>'+adminSafe(product.name||product.external_id||'Untitled product')+'</td><td>'+adminSafe(product.displaySkus)+'</td><td>'+ (product.visible?'ON':'OFF')+'</td><td>'+adminSafe(product.id)+'</td></tr>').join('')||'<tr><td colspan="4">No uncategorized products found.</td></tr>';status.textContent=uncategorized.length+' uncategorized product'+(uncategorized.length===1?'':'s')+' found.';view.querySelector('[data-download-uncategorized-report]').onclick=()=>{const link=document.createElement('a');const csv=[['Product','SKU(s)','Storefront','Product ID'],...uncategorized.map((product)=>[product.name||product.external_id||'Untitled product',product.displaySkus,product.visible?'ON':'OFF',product.id])].map((row)=>row.map((value)=>'"'+String(value??'').replace(/"/g,'""')+'"').join(',')).join('\n');link.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));link.download='uncategorized-products.csv';link.click();};view.querySelector('[data-refresh-uncategorized-report]').onclick=()=>void renderAdminUncategorizedReportTab();}catch(error){status.textContent='Unable to load uncategorized products: '+error.message;}};
